import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"技能概述","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills.md","filePath":"guide/skills.md","lastUpdated":1792083729000}'),o={name:"guide/skills.md"};function c(l,t,h,n,i,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="技能概述" tabindex="-1">技能概述 <a class="header-anchor" href="#技能概述" aria-label="Permalink to &quot;技能概述&quot;">​</a></h1><p>技能系统是 FunGame 的核心。所有技能都需<strong>继承 <code>Skill</code> 类</strong>来构造。</p><p><strong>技能与特效的关系</strong>：特效寄生于技能中，一个技能由数个特效构成，特效承载着技能的实际效果。技能负责消耗、冷却、目标选择等框架行为，具体效果由特效实现。详见 <a href="./effects.html">特效概述</a>。</p><h2 id="技能类型" tabindex="-1">技能类型 <a class="header-anchor" href="#技能类型" aria-label="Permalink to &quot;技能类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>消耗</th><th>吟唱</th><th>升级</th><th>说明</th></tr></thead><tbody><tr><td>普通攻击</td><td>决策点</td><td>❌</td><td>1-8 级</td><td>基于攻击力的物理伤害，最常见的攻击方式</td></tr><tr><td>主动战技</td><td>爆发能量</td><td>❌</td><td>1-6 级</td><td>需学习，直接发动技能效果</td></tr><tr><td>被动战技</td><td>—</td><td>❌</td><td>通常 1 级</td><td>随时判断条件是否成立并生效</td></tr><tr><td>爆发技</td><td>爆发能量</td><td>❌</td><td>1-6 级</td><td>无视行动顺序，回合外可预释放插队</td></tr><tr><td>魔法</td><td>魔法值</td><td>✅</td><td>1-8 级</td><td>吟唱后生效</td></tr><tr><td>战斗天赋</td><td>—</td><td>❌</td><td>—</td><td>按定位获取的被动，属于被动战技</td></tr></tbody></table><h2 id="技能升级" tabindex="-1">技能升级 <a class="header-anchor" href="#技能升级" aria-label="Permalink to &quot;技能升级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能类型</th><th>最高等级</th><th>升级所需等级</th></tr></thead><tbody><tr><td>普通攻击</td><td>8</td><td>8/16/24/32/40/48/56</td></tr><tr><td>主动战技</td><td>6</td><td>12/24/36/48/60</td></tr><tr><td>爆发技</td><td>6</td><td>12/24/36/48/60</td></tr><tr><td>魔法</td><td>8</td><td>8/16/24/32/40/48/56</td></tr></tbody></table><blockquote><p>被动战技通常没有升级选项；魔法卡包的魔法等级通过魔法卡升级，没有等级要求。</p></blockquote><h2 id="施法距离" tabindex="-1">施法距离 <a class="header-anchor" href="#施法距离" aria-label="Permalink to &quot;施法距离&quot;">​</a></h2><p>施法距离是技能生效的距离限制（战棋地图上的曼哈顿距离）：</p><table tabindex="0"><thead><tr><th>技能类型</th><th>施法距离</th></tr></thead><tbody><tr><td>普通攻击</td><td>默认跟随角色攻击距离，可单独配置 <code>AttackRange</code>；<code>AttackAnywhere</code> 或全选使其全图生效</td></tr><tr><td>主动战技 / 爆发技</td><td>使用 <code>CastRange</code>，<code>CastAnywhere</code> 或全选使其全图生效</td></tr><tr><td>魔法</td><td>全地图，即没有距离限制</td></tr><tr><td>被动战技</td><td>默认全地图生效；部分被动战技也有距离限制——确切地说，是指<strong>生效范围</strong></td></tr></tbody></table><p><code>CastRange</code> 是施法者到目标或落点的射程，<code>CanSelectTargetRange</code> 是目标周围的效果扩散半径，两者不可互换。全图状态下读取的有效射程与原始设置分开保存，关闭全选后可恢复配置值。</p><h2 id="全选目标" tabindex="-1">全选目标 <a class="header-anchor" href="#全选目标" aria-label="Permalink to &quot;全选目标&quot;">​</a></h2><p>技能或普攻启用 <code>SelectAllEnemies</code> / <code>SelectAllTeammates</code> 后，以全图指向性方式选取合法敌方 / 友方；同时启用时取并集。<code>CanSelectEnemy</code>、<code>CanSelectTeammate</code>、免疫和目标谓词仍生效，自身只有在全选友方且 <code>CanSelectSelf</code> 允许时才纳入。</p><p>全选优先于 <code>CanSelectTargetCount</code>、范围中心和目标周围扩散，不再从选中目标继续扩张目标集合。技能特效仍对最终合法目标正常结算。AI、手动选择、协同申请与执行前重验使用同一规则。</p><p><code>IsNonDirectional</code> 在全选期间返回 false；JSON 保留原始方向性、射程及全选标志，反序列化后继续按这些配置派生有效值。</p><h2 id="技能范围类型-skillrangetype" tabindex="-1">技能范围类型 (SkillRangeType) <a class="header-anchor" href="#技能范围类型-skillrangetype" aria-label="Permalink to &quot;技能范围类型 (SkillRangeType)&quot;">​</a></h2><p>非指向性技能可以选择不同的范围形状：</p><table tabindex="0"><thead><tr><th>形状</th><th>枚举值</th><th>说明</th></tr></thead><tbody><tr><td>菱形</td><td><code>Diamond</code></td><td>以目标为中心的菱形区域</td></tr><tr><td>圆形</td><td><code>Circle</code></td><td>以目标为中心的圆形区域</td></tr><tr><td>正方形</td><td><code>Square</code></td><td>以目标为中心的正方形区域</td></tr><tr><td>线段</td><td><code>Line</code></td><td>施法者到目标之间的线段</td></tr><tr><td>贯通线</td><td><code>LinePass</code></td><td>施法者到目标的直线，贯穿至地图边缘</td></tr><tr><td>扇形</td><td><code>Sector</code></td><td>以施法者为圆心的扇形区域</td></tr></tbody></table><h2 id="魔法属性-magictype" tabindex="-1">魔法属性 (MagicType) <a class="header-anchor" href="#魔法属性-magictype" aria-label="Permalink to &quot;魔法属性 (MagicType)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>枚举值</th><th>伤害名称</th></tr></thead><tbody><tr><td>无</td><td><code>None</code></td><td>魔法伤害</td></tr><tr><td>星痕</td><td><code>Starmark</code></td><td>星痕魔法伤害</td></tr><tr><td>纯粹结晶</td><td><code>PurityContemporary</code></td><td>纯粹结晶魔法伤害</td></tr><tr><td>现代结晶</td><td><code>PurityNatural</code></td><td>现代结晶魔法伤害</td></tr><tr><td>光</td><td><code>Bright</code></td><td>光魔法伤害</td></tr><tr><td>影</td><td><code>Shadow</code></td><td>影魔法伤害</td></tr><tr><td>元素</td><td><code>Element</code></td><td>元素魔法伤害</td></tr><tr><td>紫宛</td><td><code>Aster</code></td><td>紫宛魔法伤害</td></tr><tr><td>时空</td><td><code>SpatioTemporal</code></td><td>时空魔法伤害</td></tr></tbody></table><p>每种魔法属性有独立的<strong>魔法抗性</strong>，但魔法穿透为共用属性。</p>',22)])])}const m=d(o,[["render",c]]);export{b as __pageData,m as default};
